insert into drafts values('v1',jsonb_build_object('schemaVersion',1,'status','draft','seeds','[]'::jsonb,'results','{}'::jsonb,
 'participants',(select jsonb_agg(jsonb_build_object('id','p'||n,'nickname','Player '||n,'characterIds','[]'::jsonb) order by n) from generate_series(1,8) n)));
insert into drafts select 'v2',jsonb_set(payload,'{schemaVersion}','2')||jsonb_build_object('structure',ss_private.draft_structure(8),'completionOrder','[]'::jsonb) from drafts where label='v1';
select pg_temp.actor(1);
set local role authenticated;
select pg_temp.assert_true(current_user='authenticated' and row_security_active('public.tournament_brackets'::regclass),'real RLS execution');
insert into test_ids values('t1',public.ss_create_tournament('Legacy fixture')),('t2',public.ss_create_tournament('Admin fixture')),('atomic',public.ss_create_tournament('Atomic rollback fixture'));
insert into test_ids select 'invite',public.ss_invite_admin((select id from test_ids where label='t2'),1,'155a0000-0000-0000-0000-000000000002');
select pg_temp.actor(2);
select pg_temp.assert_true(public.ss_accept_admin_invitation((select id from test_ids where label='invite'),2)=3,'admin accepted');
set local role postgres;
-- Deliberate fixture-only audit collision: force failure AFTER roster/state writes.
insert into public.tournament_revisions(tournament_id,revision,actor_id,action,changes)
 select id,2,'155a0000-0000-0000-0000-000000000001','fixture_collision','{}' from test_ids where label='atomic';
select pg_temp.actor(1);
set local role authenticated;
select pg_temp.expect_state($q$select public.ss_initialize_tournament_draft((select id from test_ids where label='atomic'),1,gen_random_uuid(),(select payload from drafts where label='v1'))$q$,'23505');
select pg_temp.assert_true((select count(*)=0 from public.tournament_participants where tournament_id=(select id from test_ids where label='atomic')),'late failure rolls back roster');
select pg_temp.assert_true((select revision=1 and state->'structure'='[]'::jsonb from public.tournament_brackets where tournament_id=(select id from test_ids where label='atomic')),'late failure rolls back state and revision');
set local role postgres;
insert into public.tournament_members(tournament_id,profile_id,role) select id,'155a0000-0000-0000-0000-000000000004','player' from test_ids where label='t1';

select pg_temp.actor(3);
set local role authenticated;
select pg_temp.expect_state($q$select public.ss_read_tournament_snapshot((select id from test_ids where label='t1'))$q$,'42501');
select pg_temp.expect_state($q$select public.ss_initialize_tournament_draft((select id from test_ids where label='t1'),1,gen_random_uuid(),(select payload from drafts where label='v1'))$q$,'42501');
select pg_temp.actor(4);
select pg_temp.expect_state($q$select public.ss_read_tournament_snapshot((select id from test_ids where label='t1'))$q$,'42501');
select pg_temp.expect_state($q$select public.ss_initialize_tournament_draft((select id from test_ids where label='t1'),1,gen_random_uuid(),(select payload from drafts where label='v1'))$q$,'42501');
select pg_temp.actor(1);
do $$ declare bad jsonb; base jsonb:=(select payload from drafts where label='v2'); t uuid:=(select id from test_ids where label='t1'); begin
  foreach bad in array array[
    base-'seeds',base-'participants',jsonb_set(base,'{status}','"started"'),jsonb_set(base,'{seeds}','["p1"]'),
    jsonb_set(base,'{results}','{"W1":{}}'),jsonb_set(base,'{schemaVersion}','"2"'),base||'{"unknown":1}'::jsonb,
    jsonb_set(base,'{structure}','[]'),jsonb_set(base,'{completionOrder}','["W1"]'),base||'{"priorities":{"W1":1}}'::jsonb,
    jsonb_set(base,'{participants,0,nickname}','""'),jsonb_set(base,'{participants,0,nickname}','"Player 2"'),
    jsonb_set(base,'{participants,0,id}','"p2"'),jsonb_set(base,'{participants,0,characterIds}','["mario"]'),
    jsonb_set(base,'{participants,0,profile_id}','"forged"'),jsonb_set(base,'{participants}','[]'),
    jsonb_set(base,'{participants,0,nickname}',to_jsonb(repeat('x',1048577)))
  ] loop
    perform pg_temp.expect_state(format('select public.ss_initialize_tournament_draft(%L,1,gen_random_uuid(),%L::jsonb)',t,bad),'22023');
  end loop;
end $$;
select pg_temp.assert_true((select count(*)=0 from public.tournament_participants where tournament_id=(select id from test_ids where label='t1')),'invalid writes leave roster empty');
select pg_temp.assert_true((select revision=1 from public.tournament_brackets where tournament_id=(select id from test_ids where label='t1')),'invalid writes preserve revision');
select pg_temp.expect_state($q$select public.ss_initialize_tournament_draft((select id from test_ids where label='t1'),null,gen_random_uuid(),(select payload from drafts where label='v1'))$q$,'40001');
select pg_temp.assert_true(public.ss_initialize_tournament_draft((select id from test_ids where label='t1'),1,'155a0000-1111-0000-0000-000000000001',(select payload from drafts where label='v1'))=2,'legacy v1 owner import');
-- Sequential stale-client simulation; real two-session blocking still requires manual verification.
select pg_temp.expect_state($q$select public.ss_initialize_tournament_draft((select id from test_ids where label='t1'),1,gen_random_uuid(),(select payload from drafts where label='v1'))$q$,'40001');
select pg_temp.expect_state($q$select public.ss_initialize_tournament_draft((select id from test_ids where label='t1'),2,gen_random_uuid(),(select payload from drafts where label='v1'))$q$,'55000');
select pg_temp.assert_true((select count(*)=8 and count(distinct id)=8 from public.tournament_participants where tournament_id=(select id from test_ids where label='t1')),'no duplicate roster on retry');
do $$ declare s jsonb:=public.ss_read_tournament_snapshot((select id from test_ids where label='t1')); begin
 perform pg_temp.assert_true(s->>'revision'='2' and s->>'import_id'='155a0000-1111-0000-0000-000000000001','read revision and link');
 perform pg_temp.assert_true(s->'state'=(select payload-'participants' from drafts where label='v1'),'legacy state preserved exactly');
 perform pg_temp.assert_true((select jsonb_agg(jsonb_build_object('id',p->'id','nickname',p->'nickname','characterIds',p->'character_ids') order by (p->>'roster_order')::integer) from jsonb_array_elements(s->'roster') a(p))=(select payload->'participants' from drafts where label='v1'),'IDs and roster order preserved');
end $$;
select pg_temp.actor(2);
select pg_temp.assert_true(public.ss_initialize_tournament_draft((select id from test_ids where label='t2'),3,'155a0000-1111-0000-0000-000000000002',(select payload from drafts where label='v2'))=4,'admin v2 import');
select pg_temp.assert_true(public.ss_read_tournament_snapshot((select id from test_ids where label='t2'))->'state'=(select payload-'participants' from drafts where label='v2'),'admin coherent read');
select pg_temp.assert_true((select actor_id=auth.uid() and changes->'after'=(select payload from drafts where label='v2') from public.tournament_revisions where tournament_id=(select id from test_ids where label='t2') and revision=4),'same-transaction audit with real actor');
select pg_temp.expect_state($q$update public.tournament_brackets set state='{}' where tournament_id=(select id from test_ids where label='t2')$q$,'42501');
select pg_temp.expect_state($q$delete from public.tournament_participants where tournament_id=(select id from test_ids where label='t2')$q$,'42501');
select pg_temp.actor(1);
select public.ss_revoke_admin((select id from test_ids where label='t2'),4,'155a0000-0000-0000-0000-000000000002');
select pg_temp.actor(2);
select pg_temp.expect_state($q$select public.ss_read_tournament_snapshot((select id from test_ids where label='t2'))$q$,'42501');
select pg_temp.expect_state($q$select public.ss_initialize_tournament_draft((select id from test_ids where label='t2'),5,gen_random_uuid(),(select payload from drafts where label='v2'))$q$,'42501');
set local role postgres;
select pg_temp.expect_state($q$select ss_private.validate_competitive_state((select id from test_ids where label='t1'),'{}')$q$,'0A000');
set local role anon;
select pg_temp.expect_state($q$select public.ss_read_tournament_snapshot('155a0000-1111-0000-0000-000000000001')$q$,'42501');
select pg_temp.expect_state($q$select public.ss_initialize_tournament_draft('155a0000-1111-0000-0000-000000000001',1,gen_random_uuid(),'{}')$q$,'42501');
set local role postgres;
rollback;
select 'PASS 06: safe initial drafts, roles, validation, stale revisions, legacy JSON, audit and no overwrite; fixtures rolled back' as result;
